#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSaleItemsII(std::vector<std::vector<int>>& items, int budget) {
        int cheapest = 2e9;
        int maxFactor = 0;
        for (const auto& it : items) {
            cheapest = std::min(cheapest, it[1]);
            maxFactor = std::max(maxFactor, it[0]);
        }
        int maxAns = budget / cheapest;
        std::vector<int> freq(maxFactor + 1, 0);
        for (const auto& it : items) freq[it[0]]++;
        std::vector<int> multiples(maxFactor + 1, 0);
        for (int i = 1; i <= maxFactor; ++i) {
            if (freq[i] > 0) {
                int count = 0;
                for (int j = i; j <= maxFactor; j += i) {
                    count += freq[j];
                }
                multiples[i] = count;
            }
        }
        for (const auto& it : items) {
            int f = it[0], p = it[1];
            if (p <= budget) {
                int totalUnlocked = multiples[f];
                int remBudget = budget - p;
                maxAns = std::max(maxAns, totalUnlocked + remBudget / cheapest);
            }
        }
        return maxAns;
    }
};

class Solution {
    public int maxSaleItemsII(int[][] items, int budget) {
        int cheapest = Integer.MAX_VALUE;
        int maxFactor = 0;
        for (int[] it : items) {
            cheapest = Math.min(cheapest, it[1]);
            maxFactor = Math.max(maxFactor, it[0]);
        }
        int maxAns = budget / cheapest;
        int[] freq = new int[maxFactor + 1];
        for (int[] it : items) freq[it[0]]++;
        int[] multiples = new int[maxFactor + 1];
        for (int i = 1; i <= maxFactor; i++) {
            if (freq[i] > 0) {
                int count = 0;
                for (int j = i; j <= maxFactor; j += i) {
                    count += freq[j];
                }
                multiples[i] = count;
            }
        }
        for (int[] it : items) {
            int f = it[0], p = it[1];
            if (p <= budget) {
                int totalUnlocked = multiples[f];
                int remBudget = budget - p;
                maxAns = Math.max(maxAns, totalUnlocked + remBudget / cheapest);
            }
        }
        return maxAns;
    }
}

