        }
    }
    for (const [f, p] of items) {
        if (p <= budget) {
            const totalUnlocked = multiples[f];
            const remBudget = budget - p;
            maxAns = Math.max(maxAns, totalUnlocked + Math.floor(remBudget / cheapest));
        }
